t.script:
//
function initWhatsappQR() {
    var app = document.getElementById('whatsapp_qr_app');
    if (!app) { console.error('[WA QR] elemento whatsapp_qr_app no encontrado'); return; }

    var qr_id = parseInt(app.dataset.qrId);
    console.log('[WA QR] init OK, qr_id=' + qr_id);

    function now() {
        var d = new Date();
        return String(d.getHours()).padStart(2,'0') + ':' +
               String(d.getMinutes()).padStart(2,'0') + ':' +
               String(d.getSeconds()).padStart(2,'0');
    }

    function setEl(id, text) {
        var el = document.getElementById(id);
        if (el) el.textContent = text;
    }

    // Convierte ASCII art QR (█ ▀ ▄) a canvas pixel-perfect
    function displayQR(text) {
        var canvas = document.getElementById('qr_canvas');
        var img    = document.getElementById('qr_img');
        var pre    = document.getElementById('qr_code_block');
        if (pre) pre.textContent = text;

        if (!text || text.indexOf('QR no encontrado') !== -1 || text.indexOf('Error') === 0) {
            canvas.style.display = 'none'; img.style.display = 'none';
            return;
        }
        if (text.indexOf('data:image/') === 0) {
            img.src = text; img.style.display = 'block'; canvas.style.display = 'none';
            return;
        }

        // Parsear ASCII art: cada carácter = 1 col, 2 filas (half-block encoding)
        var lines = text.split('\n');
        while (lines.length && !lines[0].trim()) lines.shift();
        while (lines.length && !lines[lines.length-1].trim()) lines.pop();
        if (!lines.length) return;

        var rows = [];
        for (var i = 0; i < lines.length; i++) {
            var line = lines[i], top = [], bot = [];
            for (var j = 0; j < line.length; j++) {
                var c = line[j];
                if (c === '\u2588' || c === '\u2593') { top.push(1); bot.push(1); } // █ ▓
                else if (c === '\u2580')              { top.push(1); bot.push(0); } // ▀
                else if (c === '\u2584')              { top.push(0); bot.push(1); } // ▄
                else                                   { top.push(0); bot.push(0); } // espacio
            }
            rows.push(top); rows.push(bot);
        }

        var numCols = 0;
        for (var r = 0; r < rows.length; r++) if (rows[r].length > numCols) numCols = rows[r].length;

        var margin = 4; // quiet zone: 4 módulos blancos en todos los bordes
        var scale = Math.max(1, Math.floor(400 / Math.max(rows.length + 2*margin, numCols + 2*margin)));
        canvas.width  = (numCols + 2*margin) * scale;
        canvas.height = (rows.length + 2*margin) * scale;
        var ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#000';
        for (var row = 0; row < rows.length; row++) {
            for (var col = 0; col < rows[row].length; col++) {
                if (rows[row][col]) ctx.fillRect((col + margin) * scale, (row + margin) * scale, scale, scale);
            }
        }
        canvas.style.display = 'block'; img.style.display = 'none';
    }

    function jsonRpc(url) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', id: 1, params: {}})
        }).then(function(r) { return r.json(); })
          .then(function(resp) {
              if (resp.error) {
                  throw new Error((resp.error.data && resp.error.data.message) || resp.error.message || JSON.stringify(resp.error));
              }
              return resp.result;
          });
    }

    function showError(msg) {
        var el = document.getElementById('qr_error_msg');
        if (el) { el.textContent = 'Error: ' + msg; el.style.display = 'block'; }
        setTimeout(function(){ if (el) el.style.display = 'none'; }, 8000);
        console.error('[WA QR] ' + msg);
    }

    function updateLogs() {
        var btn = document.getElementById('update_logs_btn');
        btn.disabled = true; btn.textContent = 'Actualizando...';
        function reset() { btn.disabled = false; btn.innerHTML = '<i class="fa fa-refresh"></i> Actualizar Logs'; }
        jsonRpc('/my/whatsapp_qr/' + qr_id + '/update_logs')
            .then(function(data) {
                if (data && data.logs) { setEl('logs_block', data.logs); }
                setEl('logs_last_update', now());
                reset();
            })
            .catch(function(err) { showError(err.message || String(err)); reset(); });
    }

    function updateQR() {
        var btn = document.getElementById('update_qr_btn');
        btn.disabled = true; btn.textContent = 'Actualizando...';
        function reset() { btn.disabled = false; btn.innerHTML = '<i class="fa fa-refresh"></i> Actualizar QR'; }
        jsonRpc('/my/whatsapp_qr/' + qr_id + '/update_qr')
            .then(function(data) {
                if (data && data.qr_code) { displayQR(data.qr_code); }
                if (data && data.logs)    { setEl('logs_block', data.logs); }
                var t = now();
                setEl('qr_last_update', t);
                setEl('logs_last_update', t);
                reset();
            })
            .catch(function(err) { showError(err.message || String(err)); reset(); });
    }

    // Timestamps iniciales — confirma que el script ejecutó
    setEl('qr_last_update', now());
    setEl('logs_last_update', now());

    // Renderizar QR inicial desde el pre oculto
    var initialQR = document.getElementById('qr_code_block');
    if (initialQR) displayQR(initialQR.textContent);

    document.getElementById('update_logs_btn').addEventListener('click', updateLogs);
    document.getElementById('update_qr_btn').addEventListener('click', updateQR);

    setInterval(function(){ updateQR(); updateLogs(); }, 15000);
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initWhatsappQR);
} else {
    initWhatsappQR();
}
//
